// Нормализуем входные данные из Zendesk или Intercom в единый формат
const items = $input.all();
const results = [];

for (const item of items) {
  const data = item.json;
  let message = '';
  let ticketId = '';
  let source = '';
  let customerName = '';
  let customerEmail = '';

  // Zendesk формат
  if (data.ticket || data.comment) {
    message = (data.comment && data.comment.body) || (data.ticket && data.ticket.description) || '';
    ticketId = (data.ticket && data.ticket.id) || '';
    source = 'zendesk';
    customerName = (data.ticket && data.ticket.requester && data.ticket.requester.name) || '';
    customerEmail = (data.ticket && data.ticket.requester && data.ticket.requester.email) || '';
  }
  // Intercom формат
  else if (data.data && data.data.item) {
    const conv = data.data.item;
    const parts = conv.conversation_parts && conv.conversation_parts.conversation_parts;
    message = (parts && parts.length > 0 && parts[parts.length - 1].body) || (conv.source && conv.source.body) || '';
    ticketId = conv.id || '';
    source = 'intercom';
    customerName = (conv.source && conv.source.author && conv.source.author.name) || '';
    customerEmail = (conv.source && conv.source.author && conv.source.author.email) || '';
  }

  // Убираем HTML-теги
  message = message.replace(/<[^>]*>/g, ' ').replace(/\s+/g, ' ').trim();

  results.push({
    json: {
      message,
      ticketId: String(ticketId),
      source,
      customerName,
      customerEmail
    }
  });
}

return results;

// Проверяем сообщение на слова-триггеры
const items = $input.all();
const results = [];

const triggerWords = [
  'отмена',
  'возврат',
  'ужасно',
  'юрист',
  'мошенники',
  'судиться'
];

// Строим регулярное выражение из слов-триггеров
const pattern = new RegExp('(' + triggerWords.join('|') + ')', 'gi');

for (const item of items) {
  const msg = (item.json.message || '').toLowerCase();
  const matches = msg.match(pattern);

  if (matches && matches.length > 0) {
    // Убираем дубликаты
    const uniqueMatches = [...new Set(matches.map(m => m.toLowerCase()))];
    results.push({
      json: {
        ...item.json,
        isNegative: true,
        triggeredWords: uniqueMatches,
        triggeredCount: uniqueMatches.length
      }
    });
  } else {
    results.push({
      json: {
        ...item.json,
        isNegative: false,
        triggeredWords: [],
        triggeredCount: 0
      }
    });
  }
}

return results;

// Формируем уведомление для менеджера
const items = $input.all();
const results = [];

for (const item of items) {
  const d = item.json;
  const sourceLabel = d.source === 'zendesk' ? 'Zendesk' : 'Intercom';

  const alertText = `🚨 *НЕГАТИВ ОБНАРУЖЕН*\n\n` +
    `📌 *Источник:* ${sourceLabel}\n` +
    `🎫 *Тикет/Чат:* #${d.ticketId}\n` +
    `👤 *Клиент:* ${d.customerName || 'Неизвестно'}\n` +
    `📧 *Email:* ${d.customerEmail || '—'}\n\n` +
    `⚠️ *Триггерные слова:* ${d.triggeredWords.join(', ')}\n` +
    `📝 *Сообщение:*\n${d.message.substring(0, 500)}${d.message.length > 500 ? '...' : ''}\n\n` +
    `⏰ *Время:* ${new Date().toLocaleString('ru-RU', { timeZone: 'Europe/Moscow' })}`;

  results.push({
    json: {
      ...d,
      alertText
    }
  });
}

return results;
